from pathlib import Path
import json
from collections import Counter

ROOT = Path(__file__).resolve().parents[1]
DATE = "2026-09-21"
NOW = "2026-09-21T07:00:00+02:00"


def load(rel, default):
    p = ROOT / rel
    return json.loads(p.read_text(encoding="utf-8")) if p.exists() else default


def save(rel, obj):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(obj, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")


def upsert(items, item, key="id", prepend=False):
    for i, old in enumerate(items):
        if isinstance(old, dict) and old.get(key) == item.get(key):
            items[i] = item
            return
    items.insert(0, item) if prepend else items.append(item)


def append_once(items, item, key=None):
    if key and isinstance(item, dict):
        if any(isinstance(x, dict) and x.get(key) == item.get(key) for x in items):
            return
    elif item in items:
        return
    items.append(item)


